   271→                    if (s.isAtLeast(minSignificance)) included.add(s.dbValue());
   272→                }
   273→                for (int i = 0; i < 3; i++) {
   274→                    ps.setString(2 + i, i < included.size() ? included.get(i) : "___none___");
