   299→        try (PreparedStatement ps = conn.prepareStatement(sql)) {
   300→            ps.setString(1, workspacePath);
   301→            ps.setLong(2, since.getEpochSecond());
   302→            try (ResultSet rs = ps.executeQuery()) {
